import React from 'react';
import type { FC } from 'react';
import { Text, useAsync } from '@wix/cli-ui-kit';
import { useVeloClient, OnboardingState } from '@wix/velo-client';
import { match } from 'variant';
import { useSiteConfig } from '../../../model.js';
import { PlatformLinksSection } from '../../PlatformLink/PlatformLinksSection.js';
import { useSiteLinks } from '../../../platform-links/resolve.js';
import { useDevEnvironment } from '../DevEnvironment.js';
import { useSiteDeploymentTopologyUpdater } from './useSiteDeploymentTopologyUpdater.js';

export const SiteDev: FC = () => {
  const { appId, siteId } = useSiteConfig();
  const { baseUrl, versionOverrideId } = useDevEnvironment();
  const veloClient = useVeloClient();
  const links = useSiteLinks({
    cmd: 'dev',
    siteId,
    overrideId: versionOverrideId,
    siteUrl: baseUrl,
  });

  const { status: gitHubOnboardingStatus } = useAsync(
    () => veloClient.getGitHubOnboardingStatus(appId),
    [appId]
  );

  useSiteDeploymentTopologyUpdater();

  const isGitHubEnabled = match(gitHubOnboardingStatus, {
    Success: ({ result }) => result?.status === OnboardingState.GITHUB_ENABLED,
    Error: () => false,
    Loading: () => false,
  });
  const visibleLinks = isGitHubEnabled
    ? links
    : links.filter((link) => link.platform !== 'editor');

  return (
    <>
      <Text>Development environment ready</Text>
      <PlatformLinksSection links={visibleLinks} />
    </>
  );
};
