import React from 'react';
import type { FC } from 'react';
import process from 'node:process';
import { Box, Text } from '@wix/cli-ui-kit';
import { useSite } from './site/index.js';
import type { ScreenState } from './screen-state.js';
import { SwitchSite } from './SwitchSite.js';
import { PlatformLinksSection } from '../../PlatformLink/PlatformLinksSection.js';
import { useAppLinks } from '../../../platform-links/resolve.js';
import { useDevEnvironment } from '../DevEnvironment.js';

interface HomeScreenProps {
  onScreenChange: (screen: ScreenState) => void;
}

export const HomeScreen: FC<HomeScreenProps> = ({ onScreenChange }) => {
  const { siteId, canChangeSite } = useSite();
  const { versionOverrideId } = useDevEnvironment();
  const links = useAppLinks({
    cmd: 'dev',
    siteId,
    overrideId: versionOverrideId,
  });

  return (
    <>
      <Box gap={1}>
        <Text>Current development site:</Text>
        <Text bold skin="info">
          {siteId}
        </Text>
        {process.stdin.isTTY && canChangeSite && (
          <SwitchSite onScreenChange={onScreenChange} />
        )}
      </Box>

      <PlatformLinksSection links={links} />
    </>
  );
};
