import React from 'react';
import type { FC } from 'react';
import { Alert, useExit } from '@wix/cli-ui-kit';
import { AppInstaller } from '@wix/cli-app-installer';
import { useProjectModel } from '../../../../model.js';

interface Props {
  onSubmit: (siteId: string) => void;
}

export const ResolveSite: FC<Props> = ({ onSubmit }) => {
  const exit = useExit();
  const { model } = useProjectModel();

  return (
    <>
      <Alert type="insight">
        You don't have a development site currently configured.
      </Alert>
      <AppInstaller
        appId={model.config.appId}
        onSubmit={(siteId) => onSubmit(siteId)}
        onError={exit}
      />
    </>
  );
};
